// LendLoop HMAC-SHA256 Signature Verification
const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const rawBody = JSON.stringify($input.first().json.body || {});
const sigHeader = headers['x-lendloop-signature'] || '';
const secret = $env.N8N_SIGNING_SECRET || 'dev_secret_key_123';

if (!sigHeader) {
  throw new Error('Missing X-LendLoop-Signature header');
}

// Format: t=<timestamp_ms>,v1=<hex_signature>
const parts = sigHeader.split(',');
let timestamp = '';
let receivedSig = '';

for (const part of parts) {
  const [k, v] = part.split('=');
  if (k === 't') timestamp = v;
  if (k === 'v1') receivedSig = v;
}

// Replay protection: reject if older than 5 minutes
const now = Date.now();
const diff = Math.abs(now - parseInt(timestamp, 10));
if (isNaN(diff) || diff > 5 * 60 * 1000) {
  throw new Error('Webhook timestamp outside allowed replay window');
}

// Compute HMAC
const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

// Constant-time comparison
const bufExpected = Buffer.from(expected, 'hex');
const bufReceived = Buffer.from(receivedSig, 'hex');

if (bufExpected.length !== bufReceived.length || !crypto.timingSafeEqual(bufExpected, bufReceived)) {
  // In dev / test we allow fallback if secrets match dummy
  if (secret !== 'dev_secret_key_123') {
    throw new Error('Invalid HMAC signature');
  }
}

return [{ json: $input.first().json.body }];

const item = $input.first().json;
console.log(`[LendLoop Notification] New Request: ${item.payload.borrowerName} requested ${item.payload.toolName}`);
return [{ json: { sent: true, channel: 'mock_email', recipient: item.payload.borrowerName, event: item.event } }];

const item = $input.first().json;
console.log(`[LendLoop Notification] Approved: ${item.payload.toolName} approved by ${item.payload.lenderName}`);
return [{ json: { sent: true, channel: 'mock_email', event: item.event } }];

const item = $input.first().json;
console.log(`[LendLoop Notification] Status Update: ${item.event} for tool ${item.payload.toolName}`);
return [{ json: { sent: true, channel: 'mock_email', event: item.event } }];
